<?php

declare(strict_types=1);

namespace Bidirekt\PhpSdk\Tests\Command;

use Bidirekt\PhpSdk\Command\CommandResult;
use Bidirekt\PhpSdk\Command\ContractToOutput;
use Bidirekt\PhpSdk\Model\Contract;
use Bidirekt\PhpSdk\Model\NamedSchema;
use Bidirekt\PhpSdk\Model\ObjectNode;
use Bidirekt\PhpSdk\Model\PrimitiveNode;
use Bidirekt\PhpSdk\Model\Property;
use Bidirekt\PhpSdk\Model\SourceLocation;
use PHPUnit\Framework\TestCase;

final class ContractToOutputTest extends TestCase
{
    private const YAML = <<<'YAML'
        # Generated by bidirekt/php-sdk. Do not edit.
        schemas:
          Pet:
            type: object
            properties:
              name:
                type: string

        YAML;

    private string $root;

    protected function setUp(): void
    {
        $this->root = sys_get_temp_dir() . '/php-sdk-contract-to-output-' . bin2hex(random_bytes(6));
        mkdir($this->root);
        $this->root = (string) realpath($this->root);
    }

    protected function tearDown(): void
    {
        self::removeDirectory($this->root);
    }

    public function testWritesTheYamlCreatingTheFolders(): void
    {
        $result = $this->output('contracts/generated.yaml', false, 'src/Pet.php:3 warning: a warning' . "\n");

        self::assertEquals(new CommandResult(0, "src/Pet.php:3 warning: a warning\n"), $result);
        self::assertSame(self::YAML, file_get_contents($this->root . '/contracts/generated.yaml'));
    }

    public function testChecksWithoutWriting(): void
    {
        $output = $this->root . '/contracts/generated.yaml';

        $missing = $this->output('contracts/generated.yaml', true);
        $writtenByMissing = file_exists($output);
        $this->output('contracts/generated.yaml', false);
        $upToDate = $this->output('contracts/generated.yaml', true);
        file_put_contents($output, "# Generated by bidirekt/php-sdk. Do not edit.\nschemas: {}\n");
        $outOfDate = $this->output('contracts/generated.yaml', true, "a.php:1 warning: a warning\n");

        self::assertEquals(new CommandResult(1, "\"contracts/generated.yaml\" does not exist: run generate without --check\n"), $missing);
        self::assertFalse($writtenByMissing);
        self::assertEquals(new CommandResult(0, ''), $upToDate);
        self::assertEquals(new CommandResult(1, "a.php:1 warning: a warning\n\"contracts/generated.yaml\" is out of date: run generate without --check\n"), $outOfDate);
        self::assertSame("# Generated by bidirekt/php-sdk. Do not edit.\nschemas: {}\n", file_get_contents($output));
    }

    public function testChecksAContractWrittenWithCrlfLineEndingsAsUpToDate(): void
    {
        mkdir($this->root . '/contracts');
        file_put_contents($this->root . '/contracts/generated.yaml', str_replace("\n", "\r\n", self::YAML));

        self::assertEquals(new CommandResult(0, ''), $this->output('contracts/generated.yaml', true));
    }

    public function testFailsWithoutAStackTraceWhenTheOutputIsAFolder(): void
    {
        mkdir($this->root . '/out');

        self::assertEquals(new CommandResult(1, "cannot write \"out\": it is a folder\n"), $this->output('out', false));
        self::assertEquals(new CommandResult(1, "cannot read \"out\": it is a folder\n"), $this->output('out', true));
    }

    public function testFailsWithoutAStackTraceWhenTheFolderCannotBeCreated(): void
    {
        file_put_contents($this->root . '/contracts', '');

        $result = $this->output('contracts/generated.yaml', false);

        self::assertSame(1, $result->exitCode);
        self::assertMatchesRegularExpression('/^cannot write "contracts\/generated.yaml": [a-z][^\n]+\n$/', $result->stderr);
    }

    private function output(string $output, bool $check, string $diagnostics = ''): CommandResult
    {
        $contract = new Contract([], [], [new NamedSchema(
            'Pet',
            new ObjectNode([new Property('name', new PrimitiveNode('string'), new SourceLocation($this->root . '/src/Pet.php', 7))]),
            new SourceLocation($this->root . '/src/Pet.php', 5),
        )]);

        return ContractToOutput::contractToOutput($contract, $this->root . '/' . $output, $check, $this->root, $diagnostics);
    }

    private static function removeDirectory(string $directory): void
    {
        foreach (array_diff((array) scandir($directory), ['.', '..']) as $entry) {
            $path = $directory . '/' . $entry;
            if (is_dir($path) && !is_link($path)) {
                self::removeDirectory($path);

                continue;
            }
            unlink($path);
        }
        rmdir($directory);
    }
}
